choose.when:
select 'VLSTREAM' protocol, cast(v.id as char) row_id, v.device_id device_id, v.device_serial serial, v.device_name device_name, v.ip_addr ip_address, case when online=1 then 'ONLINE' when online=0 then 'OFFLINE' else 'UNKNOWN' end state, v.latitude latitude, v.longitude longitude, null device_type, null address, v.visibility visibility, 'OWNER' viewer_access, null my_access_request_status from wvp_vlstream_device v
=#{tenantId}
order by v.id

select 'ISUP' protocol, cast(v.id as char) row_id, v.device_id device_id, v.device_serial serial, v.name device_name, v.ip_address ip_address, v.status state, v.lat latitude, v.lng longitude, null device_type, v.address_map address
from isup_device v left join sys_dept d on v.dept_id=d.dept_id

    #{tenantId}=#{defaultTenantId}
    ${params.dataScope}

order by v.id

select 'EHOME' protocol, cast(v.id as char) row_id, v.device_id device_id, v.device_serial serial, v.name device_name, v.ip_address ip_address, v.status state, null latitude, null longitude, null device_type, null address
from ehome_device v left join sys_dept d on v.dept_id=d.dept_id

    #{tenantId}=#{defaultTenantId}
    ${params.dataScope}

order by v.id

select 'RTSP' protocol, cast(v.id as char) row_id, null device_id, null serial, v.name device_name, v.ip ip_address, null state, v.lat latitude, v.lng longitude, null device_type, v.address_map address, v.play_type play_type, v.channel channel from rtsp_device v left join sys_dept d on v.dept_id=d.dept_id
(v.tenant_id = #{tenantId} or v.tenant_id is null or v.tenant_id = '') ${params.dataScope}
order by v.id

select 'ONVIF' protocol, cast(v.id as char) row_id, null device_id, null serial, v.name device_name, v.ip ip_address, null state, v.lat latitude, v.lng longitude, null device_type, v.address_map address, v.play_type play_type, v.channel channel from onvif_device v left join sys_dept d on v.dept_id=d.dept_id
(v.tenant_id = #{tenantId} or v.tenant_id is null or v.tenant_id = '') ${params.dataScope}
order by v.id

select 'GB28181' protocol, cast(v.id as char) row_id, v.device_id device_id, null serial, v.name device_name, v.ip ip_address, case when on_line=1 then 'ONLINE' when on_line=0 then 'OFFLINE' else 'UNKNOWN' end state, v.lat latitude, v.lng longitude, null device_type, null address
from wvp_device v left join sys_dept d on v.dept_id=d.dept_id

    #{tenantId}=#{defaultTenantId}
    ${params.dataScope}

order by v.id

select 'DAHUA' protocol, cast(v.id as char) row_id, v.device_id device_id, null serial, v.name device_name, v.ip ip_address, null state, v.lat latitude, v.lng longitude, null device_type, v.address_map address
from dahua_device v left join sys_dept d on v.dept_id=d.dept_id

    #{tenantId}=#{defaultTenantId}
    ${params.dataScope}

order by v.id

select 'CUSTOM' protocol, cast(v.id as char) row_id, v.device_code device_id, null serial, v.device_name device_name, null ip_address, v.status state, v.latitude latitude, v.longitude longitude, v.device_type device_type, v.address address from wvp_custom_device v
#{tenantId}=#{defaultTenantId}
order by v.id

mapper.select:
select 'VLSTREAM' protocol, ref.access_ref row_id, null device_id, null serial, v.device_name device_name, null ip_address, case when v.visibility='PUBLIC' or g.grant_id is not null then case when v.online=1 then 'ONLINE' when v.online=0 then 'OFFLINE' else 'UNKNOWN' end else null end state, case when v.visibility='PUBLIC' or g.grant_id is not null then v.latitude else null end latitude, case when v.visibility='PUBLIC' or g.grant_id is not null then v.longitude else null end longitude, null device_type, null address, v.visibility visibility, case when v.visibility='PUBLIC' then 'PUBLIC' when g.grant_id is not null then 'GRANTED' when latest_request.status='PENDING' then 'PENDING' else 'NONE' end viewer_access, case when g.grant_id is not null then 'APPROVED' when latest_request.status='APPROVED' and prior_grant.revoked_at is not null then 'REVOKED' when latest_request.status='APPROVED' and prior_grant.expires_at <= NOW() then 'EXPIRED' else latest_request.status end my_access_request_status from wvp_vlstream_device v inner join wvp_vlstream_device_access_ref ref on ref.device_row_id=v.id left join ( select device_row_id, max(grant_id) grant_id from wvp_vlstream_access_grant where viewer_tenant_id=#{tenantId} and revoked_at is null and expires_at > NOW() group by device_row_id ) g on g.device_row_id=v.id left join ( select device_row_id, max(request_id) request_id from wvp_vlstream_access_request where requester_tenant_id=#{tenantId} group by device_row_id ) r on r.device_row_id=v.id left join wvp_vlstream_access_request latest_request on latest_request.request_id=r.request_id left join wvp_vlstream_access_grant prior_grant on prior_grant.grant_id=latest_request.resolved_grant_id where <> #{tenantId}
and v.device_name like concat('%',#{keyword},'%')
order by v.id
